/* KAGE — the three garden stills as data: URLs. Under file:// an image read
   from disk taints any canvas it is drawn into, and the cloth uploads that
   canvas to WebGL; a data: URL does not taint. Keyed by file name. */
window.KagePlates = {
  'kage-approach.webp': 'data:image/webp;base64,',
  'kage-lantern-court.webp': 'data:image/webp;base64,',
  'kage-moonwater.webp': 'data:image/webp;base64,',
};
